def _pull_and_checkout_outs(self) -> None:
    """Pull missing outputs from remote and checkout to workspace."""
    from dvc.utils import big_file_size, big_file_traceback

    used_objs = self.get_used_objs()
    for odb, objs in used_objs.items():
        if objs:
            self.repo.cloud.pull(objs)

    self._checkout_outs()

def _checkout_outs(self, allow_missing: bool = False) -> None:
    """Checkout outputs from cache."""
    from dvc.exceptions import OutputDoesNotExistError

    for out in self.outs:
        if out.hash_info and not out.exists:
            try:
                out.checkout(allow_missing=allow_missing)
            except OutputDoesNotExistError:
                logger.warning(
                    big_file_traceback.format(
                        path=str(out),
                        size=big_file_size(out),
                    )
                )
                raise

